/**
 * Chat Types for System Prompt Enhancement
 *
 * TypeScript interfaces for session management, clarification logic,
 * and conversation context tracking.
 *
 * Related PRD: 0006-prd-system-prompt-enhancement-guardrails.md
 */

/**
 * Dialogue Phase
 * Tracks current phase of conversation to prevent loops
 * Related: tasks-0006-prd-system-prompt-enhancement-guardrails-LOOP-FIX.md (Sub-task 9.9)
 */
export type DialoguePhase = 'clarification' | 'recommendation' | 'follow-up';

/**
 * Clarification Type
 * Types of clarifications that can be asked
 */
export type ClarificationType = 'gender' | 'occasion' | 'destination' | 'budget';

/**
 * Session Context for Duplicate Prevention
 * Tracks products recommended during the current chat session
 * Enhanced with loop prevention tracking (v2.1)
 */
export interface SessionContext {
  /** Array of product SKUs/IDs already recommended in this session */
  recommendedProductIds: string[];
  /** Optional session identifier for tracking */
  sessionId?: string;
  /** Timestamp when session was created */
  createdAt?: Date;
  /** Track which clarifications have been asked to prevent loops (Array for JSON serialization) */
  askedClarifications: ClarificationType[];
  /** Extracted information from conversation history */
  conversationContext: {
    gender?: 'men' | 'women';
    occasion?: string;
    destination?: string;
    budget?: number;
  };
  /**
   * Current dialogue phase (v2.1 - Loop Prevention)
   * - 'clarification': Asking questions (max 2)
   * - 'recommendation': Providing outfit/tips
   * - 'follow-up': Handling adjustments/refinements
   */
  dialoguePhase?: DialoguePhase;
  /**
   * Count of clarification turns (v2.1 - Loop Prevention)
   * Used to enforce MAX 2 clarifications rule
   */
  clarificationTurnCount?: number;
}

/**
 * Conversation Memory
 * Stores user context extracted from conversation history
 */
export interface ConversationMemory {
  /** User's gender preference (if specified) */
  gender?: 'men' | 'women';
  /** User's budget range */
  budget?: number;
  /** Occasion for outfit (work, wedding, date, etc.) */
  occasion?: string;
  /** Travel destination (for travel-related queries) */
  destination?: string;
  /** Climate/season context */
  climate?: string;
  /** User's style preferences */
  stylePreferences?: string[];
  /** Session context for duplicate tracking */
  sessionContext: SessionContext;
}

/**
 * Clarification Needed
 * Represents a clarification question that should be asked
 */
export interface ClarificationNeeded {
  /** Type of clarification needed */
  type: 'gender' | 'occasion' | 'destination' | 'budget';
  /** The question to ask the user */
  question: string;
  /** Priority level (1 = highest) */
  priority: number;
}

/**
 * User Query
 * Parsed user query with detected information
 */
export interface UserQuery {
  /** Original user message */
  message: string;
  /** Whether gender was specified or can be inferred */
  hasGender: boolean;
  /** Whether occasion was specified or can be inferred */
  hasOccasion: boolean;
  /** Whether budget was mentioned */
  hasBudget: boolean;
  /** Whether destination was mentioned (for travel queries) */
  hasDestination: boolean;
  /** Whether this is a travel-related query */
  isTravelQuery: boolean;
  /** Detected gender (if any) */
  detectedGender?: 'men' | 'women';
  /** Detected occasion (if any) */
  detectedOccasion?: string;
  /** Detected budget (if any) */
  detectedBudget?: number;
  /** Detected destination (if any) */
  detectedDestination?: string;
}

/**
 * Guardrail Category
 * Categories of off-topic queries
 */
export type GuardrailCategory =
  | 'health'
  | 'technology'
  | 'food'
  | 'general'
  | 'travel'
  | 'inappropriate'
  | 'default';

/**
 * Redirect Message Map
 * Maps guardrail categories to redirect messages
 */
export interface RedirectMessageMap {
  health: string;
  technology: string;
  food: string;
  general: string;
  travel: string;
  inappropriate: string;
  default: string;
}

/**
 * System Prompt Version
 * Supported system prompt versions
 */
export type SystemPromptVersion = 'v1' | 'v2';

/**
 * Prompt Version (v3.0 - for A/B testing)
 * Available prompt versions for switching between v2.1 and v3.0
 * Related PRD: 0007-prd-system-prompt-v3-clarification-fix.md
 */
export type PromptVersion = 'v2.1' | 'v3.0';

/**
 * System Prompt Metadata
 * Metadata about the system prompt
 */
export interface SystemPromptMetadata {
  version: SystemPromptVersion;
  createdAt: string;
  lastUpdated: string;
  description: string;
  enhancements?: string[];
}

/**
 * Session Context Utilities
 *
 * Manages session-based product tracking for duplicate prevention.
 * Provides functions to create, update, and reset session context.
 *
 * Related PRD: 0006-prd-system-prompt-enhancement-guardrails.md
 * Task: 3.1 - Create session context utilities
 *
 * @version 1.0.0
 * @created 2025-10-14
 */

import type { SessionContext } from '../types/chat-types';

/**
 * Creates a new session context
 *
 * @param sessionId - Optional session identifier
 * @returns New SessionContext object
 */
export function createSessionContext(sessionId?: string): SessionContext {
  return {
    recommendedProductIds: [],
    sessionId: sessionId || generateSessionId(),
    createdAt: new Date(),
    askedClarifications: [], // Array instead of Set for JSON serialization
    conversationContext: {},
    dialoguePhase: 'clarification', // Start in clarification phase (v2.1)
    clarificationTurnCount: 0, // Track clarification turns (v2.1)
  };
}

/**
 * Updates session context with newly recommended products
 *
 * @param context - Current session context
 * @param newProductIds - Array of newly recommended product SKUs
 * @param askedClarification - Type of clarification that was just asked (if any)
 * @param conversationContext - Updated conversation context (if any)
 * @returns Updated SessionContext object
 */
export function updateSessionContext(
  context: SessionContext,
  newProductIds: string[],
  askedClarification?: 'gender' | 'occasion' | 'destination' | 'budget',
  conversationContext?: Partial<SessionContext['conversationContext']>
): SessionContext {
  // Use Set to avoid duplicates within the update itself
  const uniqueIds = new Set([...context.recommendedProductIds, ...newProductIds]);

  // Update asked clarifications (using Array to avoid duplicates)
  const currentAsked = context.askedClarifications || [];
  const updatedAskedClarifications = askedClarification && !currentAsked.includes(askedClarification)
    ? [...currentAsked, askedClarification]
    : currentAsked;

  // Update conversation context
  const updatedConversationContext = {
    ...context.conversationContext,
    ...conversationContext,
  };

  // Update dialogue phase and turn count (v2.1 - Loop Prevention)
  let dialoguePhase = context.dialoguePhase || 'clarification';
  let clarificationTurnCount = context.clarificationTurnCount || 0;

  // If asking a clarification, increment turn count and stay in clarification phase
  if (askedClarification) {
    clarificationTurnCount = updatedAskedClarifications.length;
    dialoguePhase = 'clarification';
  }

  // If recommending products, transition to recommendation phase
  if (newProductIds.length > 0) {
    dialoguePhase = 'recommendation';
  }

  // If already recommended and asking again (refinement), move to follow-up
  if (context.recommendedProductIds.length > 0 && newProductIds.length > 0) {
    dialoguePhase = 'follow-up';
  }

  return {
    ...context,
    recommendedProductIds: Array.from(uniqueIds),
    askedClarifications: updatedAskedClarifications,
    conversationContext: updatedConversationContext,
    dialoguePhase,
    clarificationTurnCount,
  };
}

/**
 * Resets session context (clears all recommended products)
 *
 * @param context - Current session context
 * @param newSessionId - Optional new session ID (generates one if not provided)
 * @returns Reset SessionContext object
 */
export function resetSessionContext(context: SessionContext, newSessionId?: string): SessionContext {
  return {
    ...context,
    recommendedProductIds: [],
    sessionId: newSessionId || generateSessionId(),
    createdAt: new Date(),
    askedClarifications: [], // Array instead of Set
    conversationContext: {},
    dialoguePhase: 'clarification', // Reset to clarification phase (v2.1)
    clarificationTurnCount: 0, // Reset turn count (v2.1)
  };
}

/**
 * Checks if a product has been recommended in this session
 *
 * @param context - Session context
 * @param productId - Product SKU to check
 * @returns True if product has been recommended
 */
export function isProductRecommended(context: SessionContext, productId: string): boolean {
  return context.recommendedProductIds.includes(productId);
}

/**
 * Gets the count of recommended products in session
 *
 * @param context - Session context
 * @returns Number of recommended products
 */
export function getRecommendedProductCount(context: SessionContext): number {
  return context.recommendedProductIds.length;
}

/**
 * Checks if session should be reset based on user message
 *
 * @param message - User message to check
 * @returns True if session should be reset
 */
export function shouldResetSession(message: string): boolean {
  const lowerMessage = message.toLowerCase();

  const resetTriggers = [
    'เริ่มใหม่',
    'ลืมการสนทนาก่อนหน้า',
    'reset',
    'start over',
    'new conversation',
    'clear history',
    'ลืมที่แนะนำไป',
    'แนะนำใหม่',
  ];

  return resetTriggers.some((trigger) => lowerMessage.includes(trigger));
}

/**
 * Generates a unique session ID
 *
 * @returns Unique session ID string
 */
function generateSessionId(): string {
  return `session-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
}

/**
 * Formats session context for AI consumption
 * Converts the context into a readable format for the AI system prompt
 *
 * @param context - Session context
 * @returns Formatted string for AI
 */
export function formatSessionContextForAI(context: SessionContext): string {
  if (context.recommendedProductIds.length === 0) {
    return 'No products recommended yet in this session.';
  }

  return `Previously recommended products in this session:
${context.recommendedProductIds.map((id, index) => `${index + 1}. ${id}`).join('\n')}

Total: ${context.recommendedProductIds.length} products

IMPORTANT: Do NOT recommend any of these products again. Filter them out before making recommendations.`;
}

/**
 * Creates a session context from conversation history
 * Useful when reconstructing session from existing conversation
 *
 * @param conversationHistory - Array of messages with product references
 * @returns SessionContext reconstructed from history
 */
export function createSessionContextFromHistory(
  conversationHistory: Array<{ role: string; content: string }>
): SessionContext {
  const productIds = new Set<string>();

  // Simple pattern matching for product IDs (e.g., "SKU-001", "CEN-123456")
  const productIdPattern = /(?:SKU-|CEN-)[\w-]+/g;

  for (const message of conversationHistory) {
    if (message.role === 'assistant') {
      const matches = message.content.match(productIdPattern);
      if (matches) {
        matches.forEach((id) => productIds.add(id));
      }
    }
  }

  return {
    recommendedProductIds: Array.from(productIds),
    sessionId: generateSessionId(),
    createdAt: new Date(),
    askedClarifications: [], // Array instead of Set
    conversationContext: {},
  };
}

/**
 * Validates session context integrity
 *
 * @param context - Session context to validate
 * @returns True if valid, false otherwise
 */
export function isValidSessionContext(context: any): context is SessionContext {
  return (
    typeof context === 'object' &&
    context !== null &&
    Array.isArray(context.recommendedProductIds) &&
    context.recommendedProductIds.every((id: any) => typeof id === 'string')
  );
}

/**
 * Comprehensive Product Type Definitions
 * Enhanced product data model for AI Fashion Assistant
 */

import type {
  AvailabilityStatus,
  Gender,
  OccasionType,
  SeasonType,
  FormalityLevel,
  FitType,
  StyleTag,
  PatternType,
  BrandTier,
  OutfitRole,
  Currency,
  SizeStandard,
  ColorName,
  MaterialType,
  TagStructure,
} from './enums'
import type { LocalizedText } from './localization-types'

/**
 * Core Product Information
 */
export interface CoreProductInfo {
  // Unique identifier (FR-001)
  id: string
  sku: string

  // Product names - bilingual support (FR-002, FR-003)
  name: LocalizedText

  // Product description (FR-038)
  description?: LocalizedText

  // Brand information (FR-033, FR-034)
  brand: string
  brandTier?: BrandTier
}

/**
 * Pricing Information
 */
export interface PricingInfo {
  // Current price (FR-006)
  currentPrice: number

  // Original price for discounts (FR-007)
  originalPrice?: number

  // Currency (FR-008, FR-039)
  currency: Currency

  // Promotional information (FR-032)
  promotional?: string

  // Calculated discount percentage
  discountPercentage?: number
}

/**
 * Classification Information
 */
export interface ClassificationInfo {
  // Hierarchical category (FR-009, FR-010)
  category: {
    department?: string // Level 1
    category?: string // Level 2
    subcategory?: string // Level 3
    type?: string // Level 4
  }

  // Gender/demographic (FR-011)
  gender: Gender

  // Flexible tags (FR-012, FR-013)
  tags: {
    occasion?: OccasionType[]
    style?: StyleTag[]
    season?: SeasonType[]
    custom?: TagStructure[]
  }

  // Outfit role (FR-014, FR-047)
  role?: OutfitRole

  // Complete outfit flag (FR-045)
  isCompleteOutfit?: boolean
}

/**
 * Style & Aesthetic Attributes
 */
export interface StyleAttributes {
  // Color information (FR-015, FR-016)
  colors: {
    primary: ColorName | string
    secondary?: (ColorName | string)[]
  }

  // Pattern (FR-017)
  pattern?: PatternType

  // Formality level 1-10 (FR-018)
  formalityLevel: FormalityLevel

  // Style tags (FR-019)
  styleAttributes: StyleTag[]

  // Material/fabric (FR-020)
  material?: MaterialType | string

  // Season/weather (FR-021)
  seasonality: SeasonType[]
}

/**
 * Size & Fit Information
 */
export interface SizeInfo {
  // Available sizes (FR-025)
  availableSizes: string[]

  // Size standard (FR-026)
  sizeStandard?: SizeStandard

  // Fit description (FR-027)
  fit?: FitType

  // Detailed measurements (FR-028)
  measurements?: {
    [size: string]: {
      chest?: number
      waist?: number
      hips?: number
      length?: number
      shoulders?: number
      unit: 'cm' | 'in'
    }
  }
}

/**
 * Availability Information
 */
export interface AvailabilityInfo {
  // Availability status (FR-029)
  status: AvailabilityStatus

  // Stock quantity (FR-030)
  stockQuantity?: number

  // Store locations (FR-043)
  storeLocations?: string[]

  // Last updated timestamp
  lastUpdated?: Date
}

/**
 * Thai Market Specific Information
 */
export interface ThaiMarketInfo {
  // Cultural appropriateness (FR-036)
  culturalAppropriate: boolean

  // Special flags (FR-037)
  specialFlags?: {
    templeAppropriate?: boolean
    conservativeWorkplaceSuitable?: boolean
    thaiWeddingSuitable?: boolean
  }

  // Thai sizing information
  thaiSizeEquivalent?: string

  // Thai fashion sensibilities metadata
  thaiStyleNotes?: string
}

/**
 * Central Group Integration
 */
export interface CentralIntegration {
  // Central's SKU (FR-040, FR-044)
  centralSKU: string

  // Product URL (FR-031, FR-041)
  productUrl: string

  // Image URLs (FR-004, FR-005, FR-042)
  images: {
    primary: string
    additional?: string[]
  }

  // Central-specific metadata
  centralMetadata?: {
    categoryPath?: string
    productCode?: string
  }
}

/**
 * Outfit Composition Support
 */
export interface OutfitComposition {
  // Recommended pairings (FR-046)
  recommendedPairings?: string[] // Array of product IDs

  // Goes well with suggestions
  goesWellWith?: {
    tops?: string[]
    bottoms?: string[]
    footwear?: string[]
    accessories?: string[]
  }

  // Styling tips (FR-057)
  stylingTips?: LocalizedText
}

/**
 * Extensibility & Future Features
 */
export interface ExtensibilityFields {
  // User interaction tracking (FR-055)
  userInteractions?: {
    views?: number
    clicks?: number
    favorites?: number
    addedToOutfit?: number
  }

  // Reviews and ratings (FR-056)
  reviews?: {
    averageRating?: number
    totalReviews?: number
  }

  // Sustainability attributes (FR-058)
  sustainability?: {
    ecoFriendly?: boolean
    sustainableMaterial?: boolean
    ethicalProduction?: boolean
    certifications?: string[]
  }

  // Virtual try-on metadata (FR-059)
  virtualTryOn?: {
    available?: boolean
    modelUrl?: string
    arCompatible?: boolean
  }

  // Care instructions (FR-035)
  careInstructions?: LocalizedText
}

/**
 * Enhanced Product - Complete Interface
 * Combines all attribute groups into comprehensive product model
 */
export interface EnhancedProduct {
  // Core information
  id: string
  sku: string
  name: LocalizedText
  description?: LocalizedText
  brand: string
  brandTier?: BrandTier

  // Pricing
  pricing: PricingInfo

  // Classification
  classification: ClassificationInfo

  // Style attributes
  style: StyleAttributes

  // Size and fit
  sizing: SizeInfo

  // Availability
  availability: AvailabilityInfo

  // Thai market specific
  thaiMarket: ThaiMarketInfo

  // Central integration
  centralIntegration: CentralIntegration

  // Outfit composition
  outfit?: OutfitComposition

  // Extensibility
  extended?: ExtensibilityFields

  // Metadata
  metadata?: {
    createdAt?: Date
    updatedAt?: Date
    version?: string
  }
}

/**
 * Simplified Product Summary for AI Context
 * Token-efficient format for AI prompts
 */
export interface ProductSummary {
  id: string
  name: string
  brand: string
  price: number
  url: string // Product URL for recommendations
  category: string
  gender: Gender
  occasions: OccasionType[]
  formality: FormalityLevel
  colors: string[]
  style: StyleTag[]
  season: SeasonType[]
  role?: OutfitRole
}

/**
 * Product Filter Criteria
 */
export interface ProductFilterCriteria {
  gender?: Gender | Gender[]
  occasions?: OccasionType | OccasionType[]
  priceRange?: { min: number; max: number }
  formality?: { min: FormalityLevel; max: FormalityLevel }
  colors?: ColorName[]
  styles?: StyleTag[]
  seasons?: SeasonType[]
  brands?: string[]
  availability?: AvailabilityStatus[]
  roles?: OutfitRole[]
}

/**
 * Product Sort Options
 */
export type ProductSortField =
  | 'price-asc'
  | 'price-desc'
  | 'formality-asc'
  | 'formality-desc'
  | 'popularity'
  | 'newest'
  | 'relevance'

/**
 * Product Query Result
 */
export interface ProductQueryResult {
  products: EnhancedProduct[]
  total: number
  page?: number
  pageSize?: number
  filters?: ProductFilterCriteria
  sort?: ProductSortField
}

