  if (context.gender) {
    const genderMap: Record<string, string> = {
      men: 'for men',
      women: 'for women',
      unisex: 'unisex style',
    };
    parts.push(genderMap[context.gender] || '');
  }

  // Extract key pieces from products
  if (context.products && context.products.length > 0) {
    const productDescriptions: string[] = [];

    // Get up to 3 key pieces
    const keyProducts = context.products.slice(0, 3);

    for (const product of keyProducts) {
      const color = product.style?.colors?.primary;
      const category = product.classification?.category?.category ||
                      product.classification?.category?.subcategory;

      if (color && category) {
        productDescriptions.push(`${color} ${category}`);
      } else if (category) {
        productDescriptions.push(category);
      }
    }

    if (productDescriptions.length > 0) {
