/**
 * Image Trigger Detection Utility
 * Detects when user wants outfit visualization and extracts context
 */

/**
 * Thai and English trigger phrases for image generation requests
 */
const IMAGE_TRIGGER_PHRASES = {
  thai: [
    'แสดงให้ดู',
    'ดูรูป',
    'อยากเห็น',
    'เห็นรูป',
    'ดูหน้าตา',
    'หน้าตาเป็นยังไง',
    'เป็นยังไงบ้าง',
    'ดูว่าเป็นยังไง',
    'ขอดูรูป',
    'มีรูปไหม',
    'แสดงรูป',
    'ภาพ',
    'visualize',
    'โชว์รูป',
    'โชว์ให้ดู',
  ],
  english: [
    'show me',
    'looks inspiration',
    'visualize',
    'what does it look like',
    'picture',
    'image',
    'can i see',
    'show picture',
    'show image',
    'display',
    'generate image',
    'create visual',
    'see how it looks',
    'view outfit',
  ],
};

/**
 * Detects if user message contains an image generation request
 * @param message - User's message text
 * @returns true if image request detected
 */
export function detectImageRequest(message: string): boolean {
  if (!message || typeof message !== 'string') {
    return false;
  }

  const normalizedMessage = message.toLowerCase().trim();

  // Check Thai trigger phrases
  for (const phrase of IMAGE_TRIGGER_PHRASES.thai) {
    if (normalizedMessage.includes(phrase.toLowerCase())) {
      return true;
    }
  }

  // Check English trigger phrases
  for (const phrase of IMAGE_TRIGGER_PHRASES.english) {
    if (normalizedMessage.includes(phrase.toLowerCase())) {
      return true;
    }
  }

  return false;
}

/**
 * Extracts outfit description from message and conversation history
 * @param message - Current user message
 * @param conversationHistory - Array of previous messages
 * @returns Extracted outfit description for image generation
 */
export function extractOutfitDescription(
  message: string,
  conversationHistory: Array<{ role: string; content: string }> = []
): string {
  // If message already contains detailed outfit description, use it
  if (message.length > 50 && !isSimpleTriggerPhrase(message)) {
    return cleanDescriptionFromMessage(message);
  }

  // Look back in conversation history for outfit context
  // Search last 5 messages for outfit recommendations from assistant
  const recentMessages = conversationHistory.slice(-5).reverse();

  for (const msg of recentMessages) {
    if (msg.role === 'assistant') {
      // Extract outfit details from assistant's response
      const outfitDescription = extractOutfitFromAssistantMessage(msg.content);
      if (outfitDescription) {
        return outfitDescription;
      }
    }
  }

  // Fallback: use the original message if no context found
  return cleanDescriptionFromMessage(message);
}

/**
 * Checks if message is just a simple trigger phrase without context
 * @param message - Message text
 * @returns true if message is a simple trigger
 */
function isSimpleTriggerPhrase(message: string): boolean {
  const normalizedMessage = message.toLowerCase().trim();

  const simplePhrases = [
    'แสดงให้ดู',
    'ดูรูป',
    'show me',
    'visualize',
    'picture',
    'image',
    'แสดงรูป',
    'โชว์ให้ดู',
  ];

  return simplePhrases.some((phrase) => normalizedMessage === phrase);
}

/**
 * Cleans and extracts outfit description from message
 * @param message - Raw message text
 * @returns Cleaned description
 */
function cleanDescriptionFromMessage(message: string): string {
  let cleaned = message;

  // Remove trigger phrases
  const allTriggers = [
    ...IMAGE_TRIGGER_PHRASES.thai,
    ...IMAGE_TRIGGER_PHRASES.english,
  ];

  for (const trigger of allTriggers) {
    const regex = new RegExp(trigger, 'gi');
    cleaned = cleaned.replace(regex, '');
  }

  // Remove common filler words
  const fillerWords = [
    'หน่อย',
    'ด้วย',
    'please',
    'ขอ',
    'อยาก',
    'want to',
    'would like',
  ];

  for (const filler of fillerWords) {
    const regex = new RegExp(`\\b${filler}\\b`, 'gi');
    cleaned = cleaned.replace(regex, '');
  }

  return cleaned.trim();
}

/**
 * Extracts outfit description from assistant's recommendation message
 * @param content - Assistant message content
 * @returns Extracted outfit description or null
 */
function extractOutfitFromAssistantMessage(content: string): string | null {
  // Look for outfit-related keywords and extract surrounding context
  const outfitKeywords = [
    'outfit',
    'ชุด',
    'เสื้อ',
    'กางเกง',
    'กระโปรง',
    'dress',
    'shirt',
    'pants',
    'skirt',
    'jacket',
    'แจ็คเก็ต',
    'look',
  ];

  const lines = content.split('\n');
  const relevantLines: string[] = [];

  for (const line of lines) {
    const normalizedLine = line.toLowerCase();
    if (outfitKeywords.some((keyword) => normalizedLine.includes(keyword))) {
      // Clean the line from markdown and special characters
      const cleaned = line
        .replace(/[*_#`]/g, '')
        .replace(/\[|\]/g, '')
        .trim();
      if (cleaned.length > 10) {
        relevantLines.push(cleaned);
      }
    }
  }

  if (relevantLines.length > 0) {
    // Join relevant lines into a comprehensive description
    return relevantLines.join('. ').substring(0, 500); // Limit to 500 chars
  }

  return null;
}

/**
 * Validates if description is sufficient for image generation
 * @param description - Outfit description
 * @returns true if description is valid
 */
export function isValidOutfitDescription(description: string): boolean {
  if (!description || typeof description !== 'string') {
    return false;
  }

  // Must be at least 10 characters
  if (description.trim().length < 10) {
    return false;
  }

  // Should contain at least one clothing-related keyword
  const clothingKeywords = [
    'outfit',
    'ชุด',
    'เสื้อ',
    'กางเกง',
    'กระโปรง',
    'dress',
    'shirt',
    'pants',
    'skirt',
    'jacket',
    'แจ็คเก็ต',
    'blazer',
    'top',
    'bottom',
    'รองเท้า',
    'shoes',
    'accessories',
    'เครื่องประดับ',
  ];

  const normalizedDescription = description.toLowerCase();
  return clothingKeywords.some((keyword) =>
    normalizedDescription.includes(keyword)
  );
}

/**
 * Creates a fashion-optimized prompt for image generation
 * @param description - Basic outfit description
 * @param additionalContext - Additional style context
 * @returns Enhanced prompt for image generation
 */
export function createFashionPrompt(
  description: string,
  additionalContext?: {
    style?: string;
    occasion?: string;
    season?: string;
  }
): string {
  const basePrompt = `Professional fashion photography of ${description}`;

  const enhancements: string[] = [];

  if (additionalContext?.style) {
    enhancements.push(`${additionalContext.style} style`);
  }

  if (additionalContext?.occasion) {
    enhancements.push(`suitable for ${additionalContext.occasion}`);
  }

  if (additionalContext?.season) {
    enhancements.push(`${additionalContext.season} collection`);
  }

  // Add Thai fashion aesthetic
  enhancements.push('Thai contemporary fashion aesthetic');
  enhancements.push('clean background');
  enhancements.push('natural lighting');
  enhancements.push('high quality');
  enhancements.push('fashionable composition');

  const fullPrompt = [basePrompt, ...enhancements].join(', ');

  return fullPrompt;
}

